function filterMarketItems(items, query) {
	const needle = query.trim().toLowerCase();
	if (!needle) return items;
	return items.filter((item) => [
		item.id,
		item.name,
		item.description,
		item.repository,
		item.author,
		...item.tags ?? []
	].some((value) => value?.toLowerCase().includes(needle)));
}
